const base='mockup/gambar-mockup/tantangan-selesai-temanggung/';
const pages=[{id:'hasil',title:'Tantangan selesai',status:'available',description:'Konsep bersama lintas wilayah. Temanggung sebagai contoh; lihat referensi pilihan dan empat keadaan UI.',brief:base+'README.md',image:base+'mockup-tantangan-selesai-temanggung-16-9.webp',preview:base+'preview-ui-lengkap.html',states:[{label:'Pilihan pengguna',kind:'selected-reference',image:base+'mockup-tantangan-selesai-temanggung-16-9.webp'},...['tampilan-utama','bahasa-terbuka','menu-terbuka','detail-hasil-terbuka'].map((s,i)=>({label:['UI utama','Bahasa','Menu','Detail hasil'][i],kind:'coded-preview',image:base+`variasi-ui/${s}/mockup-ui-${s}-16-9.webp`}))]}];
for(const [id,title,priority,views,composition,states,keys,audio] of plans){
 const folder=`mockup/persiapan/${id}`;
 const assets=keys.split(',').map(k=>{const a=d.find(x=>x.key===k);if(!a)throw Error('Missing planned asset '+k);return `| ${k} | [${a.title}](../../../${a.file}) | Pakai ulang; review individual saat mockup dibuat |`;}).join('\n');
 const prompt=`Use case: ui-mockup. Create a COMPLETE GELITA educational adventure game screen for “${title}”, exactly 1920 × 1080, fixed landscape 16:9. Premium warm stylized 3D environments, midnight navy panels, restrained antique-gold bevels, cream readable text. Match the user-selected challenge-result reference and assets/referensi/reference.01.webp for Jaka (cream shirt, red scarf, brown shorts, batik waist cloth, sandals, leather backpack). Mbah Kedu follows reference.02 without Jaka's scarf. Composition: ${composition} Maintain consistent top HUD with Indonesia/UK flag language selector, speaker and menu. Include the full interface, content hierarchy and all primary controls. Required state for the first image: ${states.split(';')[0]}. Use minimal Indonesian placeholder text; keep critical labels editable in HTML later. No invented quiz answers, real personal data, extra costume, painterly 2D, watermark, portrait reflow or background-only image. Assets to reuse: ${keys}. Preserve cultural details; mark factual content pending review. This is a proposed next mockup, not an approved design.`;
 write(folder+'/prompt-detail.md',`# Prompt mockup — ${title}\n\nStatus: **siap dibuat; gambar belum dibuat dan belum disetujui**. Prompt rencana ini bukan prompt generasi yang sudah digunakan.\n\n\`\`\`text\n${prompt}\n\`\`\`\n\n[Brief halaman](README.md) · [Arah visual](../ARAH-VISUAL.md).`);
 write(folder+'/README.md',`# Persiapan mockup — ${title}\n\nStatus **brief siap; belum ada desain visual baru**. Prioritas ${priority}, usulan urutan kerja 14 Oktober 2026, Asia/Bangkok.\n\n## Tujuan dan halaman asal\n\nBahan redesain untuk layar aplikasi \`${views}\` (lokasi diperiksa pada app/Views/game di aplikasi induk; tidak disalin atau diubah). Pertahankan fungsi/navigasi/state aktual saat diintegrasikan.\n\n## Komposisi 16:9\n\n${composition}\n\nKanvas desain 1920 × 1080; skala seragam tanpa reflow potret. HUD memakai bendera Indonesia/UK terbaru, speaker dan menu seperti konsep hasil bersama. Ukuran kontrol harus diperiksa setelah penskalaan, dengan sasaran minimal 44 px.\n\n## Aset awal\n\n| Kode slot | Sumber lokal | Perlakuan |\n|---|---|---|\n${assets}\n\nBahan di atas adalah awal pemetaan. Panel/ornamen baru hanya dibuat setelah komposisi dipilih; kode slot baru ditentukan saat integrasi katalog. Jangan mengganti media faktual menjadi ilustrasi dekoratif tanpa dasar.\n\n## Keadaan yang perlu diperlihatkan\n\n${states.split(';').map(s=>'- '+s.trim()).join('\n')}\n\nBahasa ID/EN, menu, speaker on/off, keyboard/fokus, loading dan error yang berlaku juga diperlihatkan dalam preview HTML. Teks mengikuti naskah/bank soal aplikasi; contoh fiktif diberi label.\n\n## Audio\n\nKode untuk preview: ${audio.split(',').map(a=>'\`'+a+'\`').join(', ')}. Berkas di [aset audio](../../../assets/audio/README.md). Tidak perlu narasi baru untuk mengulas visual. Suara hanya aktif setelah tindakan pengguna; volume musik lebih rendah daripada efek.\n\n## Hasil yang harus diserahkan\n\n- Mockup full UI WebP 1920 × 1080, bukan hanya latar.\n- Preview HTML/CSS/JS dengan teks dan kontrol hidup, memakai aset relatif lokal.\n- Gambar keadaan per subfolder, pemetaan aset, prompt aktual dan provenance.\n- Catatan keputusan pengguna dan hasil browser; status berubah hanya sesuai pekerjaan nyata.\n\n## Kriteria review\n\nTeks terbaca, kontrol tidak menutupi isi, panjang English tidak memecahkan layout, warna/latar/karakter konsisten, semua berkas tersedia lokal. Uji interaksi yang berlaku dan gambar full UI; catat integrasi, budaya, lisensi dan audio yang belum ditinjau. Jangan menyatakan mockup dipilih sebelum pengguna memilihnya.\n\n[Prompt siap pakai](prompt-detail.md) · [Arah visual](../ARAH-VISUAL.md) · [Alur produksi](../ALUR-PRODUKSI.md) · [Daftar rencana](../README.md).`);
 pages.push({id,title,status:'planned',priority,description:composition,brief:folder+'/README.md',prompt:folder+'/prompt-detail.md'});
}
write('mockup/catalog.json',JSON.stringify({revision:'2026-10-14',canvas:{width:1920,height:1080},pages},null,2));
write('mockup/persiapan/README.md',`# Rencana redesain mockup berikutnya\n\nDibuat 14 Oktober 2026, Asia/Bangkok. **12 paket brief siap, tanpa gambar baru atau persetujuan desain.** Urutan P1/P2 adalah usulan untuk memulai dari halaman yang paling sering dipakai; bukan keputusan produk yang sudah dikonfirmasi. Mockup hasil bersama yang sudah dipilih tetap menjadi acuan.\n\n| Halaman | Prioritas | Dokumen |\n|---|---|---|\n${plans.map(([id,title,p])=>`| ${title} | ${p} | [Brief](${id}/README.md) · [Prompt](${id}/prompt-detail.md) |`).join('\n')}\n\n[Arah visual](ARAH-VISUAL.md) · [Alur produksi](ALUR-PRODUKSI.md) · [Template keputusan](TEMPLATE-KEPUTUSAN.md) · [Template pemeriksaan](TEMPLATE-PEMERIKSAAN.md).\n\nInventaris galeri ada di [catalog.json](../catalog.json), ditanam oleh build agar halaman berfungsi melalui file lokal. Jangan mengisi image/preview pada halaman planned sampai berkas tersedia. Mockup merupakan koleksi halaman tersendiri; gambar turunan keadaan UI tidak menambah 514 entri aset utama.\n\n[Buka galeri katalog](../../index.html#mockups) · [Mockup hasil pilihan](../gambar-mockup/tantangan-selesai-temanggung/README.md).`);
console.log('Prepared 12 page briefs and prompts, plus mockup catalogue inventory.');
